//! What damages the map (Y11S3): the damage ids of the records of a damage
//! list (see [`crate::world`]) and the assets of breach devices.
//!
//! Generated by `SP\D\gen_tables.py` (SP = C:\Users\Mark\AppData\Local\Temp\claude\D--Development-replay-analyzer\
//! 4552b641-01d1-48d9-bf84-1627e02cf63c\scratchpad)
//! from `causes.json` and `device_assets.json` there, which were built
//! from 184 rounds. Do not edit by hand.

use Category::*;

/// What kind of thing a cause is.
#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Category {
    Melee,
    Ability,
    Reinforcement,
    HardBreach,
    SoftBreach,
    Explosive,
    Placement,
    Physics,
    Environment,
    Unknown,
}

/// What a damage id stands for.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Cause {
    pub id: u64,
    pub name: &'static str,
    pub category: Category,
    /// It removes material from a soft wall or floor. From how the game
    /// behaves, not from a field.
    pub holes: bool,
    /// It opens reinforcements: their intact flag was seen cleared after
    /// it.
    pub hard: bool,
    /// What the id stands for was worked out by exclusion or behaviour;
    /// the others were confirmed by the entity or the player that did it.
    pub inferred: bool,
}

const fn c(
    id: u64,
    name: &'static str,
    category: Category,
    holes: bool,
    hard: bool,
    inferred: bool,
) -> Cause {
    Cause {
        id,
        name,
        category,
        holes,
        hard,
        inferred,
    }
}

