/// The cause a damage id stands for.
pub(crate) fn cause(id: u64) -> Option<&'static Cause> {
    CAUSES.iter().find(|c| c.id == id)
}

/// A breach device a player places.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Device {
    HardBreachCharge,
    ExothermicCharge,
    Selma,
    BreachCharge,
}

impl Device {
    pub(crate) fn name(self) -> &'static str {
        match self {
            Device::HardBreachCharge => "Hard Breach Charge",
            Device::ExothermicCharge => "Exothermic Charge",
            Device::Selma => "S.E.L.M.A. Aqua Breacher",
            Device::BreachCharge => "Breach Charge",
        }
    }

    /// The device a loadout names so.
    pub(crate) fn named(name: &str) -> Option<Device> {
        [
            Device::HardBreachCharge,
            Device::ExothermicCharge,
            Device::BreachCharge,
        ]
        .into_iter()
        .find(|d| d.name() == name)
    }
}

